    }

    public record Report(int accepted, int rejected, List<Outcome> outcomes) {
    }

    public static final class ClaimValidationException extends Exception {
        private final String claimId;

        public ClaimValidationException(String claimId, String message) {
            super(message);
            this.claimId = claimId;
        }

        public String getClaimId() {
            return claimId;
        }
    }

    public interface ClaimRule {
        void check(Claim claim) throws ClaimValidationException;
    }

    private final List<ClaimRule> rules;

    public ClaimBatchProcessor(List<ClaimRule> rules) {
        this.rules = List.copyOf(Objects.requireNonNull(rules, "rules"));
    }

    public static ClaimRule requiredPolicy() {
        return claim -> {
            if (claim.policyNumber() == null || claim.policyNumber().isBlank()) {
                throw new ClaimValidationException(claim.id(), "policy number is required");
            }
        };
    }

    public static ClaimRule positiveAmount() {
        return claim -> {
            if (claim.amount() == null || claim.amount().signum() <= 0) {
                throw new ClaimValidationException(claim.id(), "amount must be positive");
            }
        };
    }

    public Report process(List<Claim> claims) {
        // TODO: run every rule for each claim. Catch ClaimValidationException and record its
        // message as the rejection reason. Catch unexpected RuntimeException as
        // "unexpected: " plus the message or the exception simple name. Keep input order,
        // ignore null claims, and use "accepted" as the accepted outcome reason.
        return new Report(0, 0, List.of());
    }
