        }

        public String getClaimId() {
            return claimId;
        }
    }

    public interface ClaimRule {
        void check(Claim claim) throws ClaimValidationException;
    }

    private final List<ClaimRule> rules;

    public ClaimBatchProcessor(List<ClaimRule> rules) {
