            }
        };
    }

    public static ClaimRule positiveAmount() {
        return claim -> {
            if (claim.amount() == null || claim.amount().signum() <= 0) {
                throw new ClaimValidationException(claim.id(), "amount must be positive");
            }
        };
    }

    public Report process(List<Claim> claims) {
        List<Outcome> outcomes = new ArrayList<>();
        int accepted = 0;
        int rejected = 0;
        if (claims != null) {
            for (Claim claim : claims) {
                if (claim == null) {
                    continue;
                }
                try {
                    for (ClaimRule rule : rules) {
                        rule.check(claim);
                    }
                    outcomes.add(new Outcome(claim.id(), true, "accepted"));
                    accepted += 1;
                } catch (ClaimValidationException error) {
                    outcomes.add(new Outcome(claim.id(), false, error.getMessage()));
                    rejected += 1;
                } catch (RuntimeException error) {
                    String message = error.getMessage() == null
                            ? error.getClass().getSimpleName() : error.getMessage();
                    outcomes.add(new Outcome(claim.id(), false, "unexpected: " + message));
                    rejected += 1;
                }
            }
        }
        return new Report(accepted, rejected, List.copyOf(outcomes));
    }

    public static final class BatchRejectedException extends RuntimeException {
        private final String claimId;
        private final List<Outcome> acceptedSoFar;

        public BatchRejectedException(String claimId, List<Outcome> acceptedSoFar) {
            super("Batch rejected at claim " + claimId);
            this.claimId = claimId;
            this.acceptedSoFar = List.copyOf(acceptedSoFar);
        }

        public String getClaimId() {
            return claimId;
        }

        public List<Outcome> getAcceptedSoFar() {
            return acceptedSoFar;
        }
    }

    public Report processStrict(List<Claim> claims) {
        List<Outcome> acceptedOutcomes = new ArrayList<>();
        if (claims != null) {
            for (Claim claim : claims) {
                if (claim == null) {
                    continue;
                }
                try {
                    for (ClaimRule rule : rules) {
                        rule.check(claim);
                    }
                    acceptedOutcomes.add(new Outcome(claim.id(), true, "accepted"));
                } catch (ClaimValidationException error) {
                    throw new BatchRejectedException(claim.id(), acceptedOutcomes);
                } catch (RuntimeException error) {
